import React from 'react';
import { Link } from 'react-router-dom';

const Header = () => {
  return (
    <header>
      <nav>
        <ul>
          <li><Link to="/">Home</Link></li>
          <li><Link to="/leave">Leave Request</Link></li>
          <li><Link to="/student-login">Student Login</Link></li>
        </ul>
      </nav>
    </header>
  );
};

export default Header;