import React, { useState } from 'react';
import axios from 'axios';

const LeaveForm = () => {
  const [leaveDetails, setLeaveDetails] = useState({ startDate: '', endDate: '', reason: '' });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const handleSubmit = async (event) => {
    event.preventDefault();
    const { startDate, endDate, reason } = leaveDetails;
    const leaveDuration = (new Date(endDate).getTime() - new Date(startDate).getTime()) / (1000 * 60 * 60 * 24);

    try {
      const endpoint = leaveDuration > 7 ? `${process.env.REACT_APP_API_URL}/api/leave/hod` : `${process.env.REACT_APP_API_URL}/api/leave/class-teacher`;
      await axios.post(endpoint, leaveDetails);
      setSuccess('Leave request submitted successfully.');
    } catch (err) {
      setError('Failed to submit leave request.');
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setLeaveDetails({ ...leaveDetails, [name]: value });
  };

  return (
    <form onSubmit={handleSubmit}>
      <input
        type="date"
        name="startDate"
        value={leaveDetails.startDate}
        onChange={handleChange}
        required
      />
      <input
        type="date"
        name="endDate"
        value={leaveDetails.endDate}
        onChange={handleChange}
        required
      />
      <textarea
        name="reason"
        placeholder="Reason for leave"
        value={leaveDetails.reason}
        onChange={handleChange}
        required
      />
      <button type="submit">Submit</button>
      {error && <div style={{ color: 'red' }}>{error}</div>}
      {success && <div style={{ color: 'green' }}>{success}</div>}
    </form>
  );
};

export default LeaveForm;