import React, { useState } from 'react';
import axios from 'axios';

const StudentLoginPage = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [userDetails, setUserDetails] = useState(null);

  const handleSubmit = async (event) => {
    event.preventDefault();
    try {
      const response = await axios.post(`${process.env.REACT_APP_API_URL}/api/student/login`, { email, password });
      setUserDetails(response.data); // Assuming the response contains user details
    } catch (err) {
      setError('Login failed. Please check your credentials.');
    }
  };

  return (
    <div>
      <h2>Student Login</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="email"
          placeholder="College Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required
        />
        <input
          type="password"
          placeholder="Password"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required
        />
        <button type="submit">Login</button>
      </form>
      {error && <div style={{ color: 'red' }}>{error}</div>}
      {userDetails && (
        <div>
          <h3>Welcome, {userDetails.name}</h3>
          <p>Branch: {userDetails.branch}</p>
          <p>Section: {userDetails.section}</p>
        </div>
      )}
    </div>
  );
};

export default StudentLoginPage;